        scene.idle(40);
        scene.overlay().showText(80).text("Setup").attachKeyFrame().placeNearTarget().pointAt(link1_2.m_252807_().m_82520_(-0.25, 0.3, 0.0));
        scene.idle(100);
        scene.rotateCameraY(180.0f);
        scene.idle(40);
        scene.overlay().showText(60).text("Counter Gauges can count the number of redstone inputs...").attachKeyFrame().placeNearTarget().pointAt(button.m_252807_().m_82520_(-0.25, 0.3, 0.0));
        scene.idle(80);
        scene.world().toggleRedstonePower(util.select().position(button));
        scene.effects().indicateRedstone(button);
        scene.world().toggleRedstonePower(util.select().position(link1_1));
        scene.world().toggleRedstonePower(util.select().position(link1_2));
        scene.idle(15);
        scene.world().toggleRedstonePower(util.select().position(button));
        scene.world().toggleRedstonePower(util.select().position(link1_1));
        scene.world().toggleRedstonePower(util.select().position(link1_2));
        scene.idle(15);
        scene.overlay().showText(60).text("And transmit it over to other panel elements").placeNearTarget().pointAt(outLink.m_252807_());

