import net.minecraft.network.chat.Component;

public class LogicGaugeScene {
    public static void logicGauge(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = GaugeHelper.simpleInit(builder, util, "logic_gauge");
        scene.world().showIndependentSection(util.select().fromTo(5, 1, 3, 1, 4, 3), Direction.NORTH);
        scene.world().showIndependentSection(util.select().fromTo(5, 3, 2, 1, 3, 2), Direction.NORTH);
        scene.idle(40);
        FactoryPanelPosition gaugePos = new FactoryPanelPosition(new BlockPos(3, 3, 2), FactoryPanelBlock.PanelSlot.TOP_RIGHT);
        BlockPos leverPos = new BlockPos(5, 3, 2);
        FactoryPanelPosition leverPos2 = new FactoryPanelPosition(new BlockPos(5, 4, 2), FactoryPanelBlock.PanelSlot.BOTTOM_RIGHT);
        BlockPos linkPos = new BlockPos(1, 3, 2);
        FactoryPanelPosition dLink = new FactoryPanelPosition(new BlockPos(1, 4, 2), FactoryPanelBlock.PanelSlot.TOP_LEFT);
        GaugeHelper.displayText((SceneBuilder)scene, gaugePos.pos(), 100, false);
        GaugeHelper.displayText((SceneBuilder)scene, leverPos, 100, true);
        GaugeHelper.displayText((SceneBuilder)scene, linkPos, 80, false);
        GaugeHelper.displayText((SceneBuilder)scene, leverPos, 100, true);
        GaugeHelper.activateRedstone((SceneBuilder)scene, leverPos);
        GaugeHelper.activateRedstone((SceneBuilder)scene, linkPos);
        GaugeHelper.setPanelPowered((SceneBuilder)scene, gaugePos, false);
        scene.idle(20);
        GaugeHelper.displayText((SceneBuilder)scene, gaugePos.pos(), 60, false);
        scene.world().toggleRedstonePower(util.select().position(leverPos));
        scene.world().toggleRedstonePower(util.select().position(linkPos));
        GaugeHelper.setPanelPowered((SceneBuilder)scene, gaugePos, true);
        scene.world().showIndependentSection(util.select().position(leverPos2.pos()), Direction.SOUTH);
        GaugeHelper.addPanelConnection((SceneBuilder)scene, gaugePos, leverPos2);
        GaugeHelper.setArrowMode((SceneBuilder)scene, gaugePos, leverPos2, 2);
        scene.idle(40);
        GaugeHelper.displayText((SceneBuilder)scene, gaugePos.pos(), 120, true);
        GaugeHelper.activateRedstone((SceneBuilder)scene, leverPos2.pos());
        GaugeHelper.activateRedstone((SceneBuilder)scene, linkPos);
        GaugeHelper.setPanelPowered((SceneBuilder)scene, gaugePos, false);
        scene.idle(40);
        scene.overlay().showControls(gaugePos.pos().m_252807_().m_82520_(-0.5, 0.0, 0.0), Pointing.DOWN, 100).rightClick();
        GaugeHelper.displayText((SceneBuilder)scene, gaugePos.pos(), 100, true);
        scene.world().toggleRedstonePower(util.select().position(linkPos));
        GaugeHelper.setPanelPowered((SceneBuilder)scene, gaugePos, true);
        scene.idle(40);

