        scene.idle(10);
        FactoryPanelPosition pickG = new FactoryPanelPosition(new BlockPos(2, 3, 2), FactoryPanelBlock.PanelSlot.BOTTOM_RIGHT);
        FactoryPanelPosition stickG = new FactoryPanelPosition(new BlockPos(3, 3, 2), FactoryPanelBlock.PanelSlot.BOTTOM_LEFT);
        FactoryPanelPosition diaG = new FactoryPanelPosition(new BlockPos(3, 4, 2), FactoryPanelBlock.PanelSlot.BOTTOM_LEFT);
        FactoryPanelPosition plaG = new FactoryPanelPosition(new BlockPos(5, 3, 2), FactoryPanelBlock.PanelSlot.BOTTOM_RIGHT);
