        scene.idle(5);
        scene.world().showSection(util.select().position(stickG.pos()), Direction.SOUTH);
        scene.idle(5);
        scene.world().showSection(util.select().position(plaG.pos()), Direction.SOUTH);
        scene.idle(5);
        scene.world().showSection(util.select().position(pickG.pos()), Direction.SOUTH);
        scene.idle(15);
        GaugeHelper.addPanelConnection(builder, pickG, diaG);
        scene.idle(5);
        GaugeHelper.addPanelConnection(builder, pickG, stickG);
        scene.idle(5);
        GaugeHelper.addPanelConnection(builder, stickG, plaG);
        scene.idle(20);
        scene.overlay().showText(60).text("").placeNearTarget().attachKeyFrame().pointAt(stickG.pos().m_252807_().m_82520_(-0.25, 0.25, 0.0));
        scene.idle(80);
        scene.overlay().showText(60).text("").placeNearTarget().pointAt(stickG.pos().m_252807_().m_82520_(-0.25, 0.25, 0.0));
        scene.idle(100);

